<script setup lang="ts">
import { ref } from 'vue'
import api from '../services/api'
import AuthShell from '../components/AuthShell.vue'
const email = ref(''); const valid = ref(false); const loading = ref(false); const error = ref(''); const sent = ref(false); const code = ref('')
const emailRule = (value: string) => /.+@.+\..+/.test(value) || 'Escribe un correo válido.'
async function recover() { if (!valid.value) return; error.value = ''; loading.value = true; try { await api.post('/auth/forgot-password', { email: email.value }); sent.value = true } catch (e: any) { error.value = e.response?.status ? 'No fue posible procesar la solicitud. Inténtalo nuevamente.' : 'No fue posible conectar con el servidor. Inténtalo nuevamente.' } finally { loading.value = false } }
</script>
<template><AuthShell eyebrow="RECUPERACIÓN DE ACCESO" title="Recupera tu contraseña" subtitle="Ingresa el correo asociado a tu cuenta para continuar con el proceso de recuperación."><div class="recovery-icon"><v-icon icon="mdi-email-lock-outline" size="27" /></div><v-alert v-if="sent" type="success" variant="tonal" class="mb-5">Si existe una cuenta con ese correo, recibirás las instrucciones de recuperación.</v-alert><v-alert v-if="error" type="error" variant="tonal" density="compact" class="mb-5" closable @click:close="error = ''">{{ error }}</v-alert><v-form v-if="!sent" v-model="valid" @submit.prevent="recover"><v-text-field v-model.trim="email" label="Correo electrónico" placeholder="correo@ejemplo.com" type="email" variant="outlined" color="primary" prepend-inner-icon="mdi-email-outline" :rules="[emailRule]" /><v-btn type="submit" block color="primary" prepend-icon="mdi-send-outline" size="large" rounded="lg" class="text-none font-weight-bold mt-3 action-btn" :loading="loading" :disabled="loading">{{ loading ? 'Enviando solicitud...' : 'Enviar instrucciones' }}</v-btn></v-form><p class="text-center text-caption text-medium-emphasis mt-6"><router-link class="small-link" to="/login">Volver al inicio de sesión</router-link></p></AuthShell></template>
<style scoped>.recovery-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:13px;background:#c3d6ea;color:#172b4d;margin:-3px 0 18px}.small-link{color:#3364a2;font-weight:700;text-decoration:none}.small-link:hover{text-decoration:underline}.action-btn{min-height:48px}.action-btn:hover{background:#3364a2!important;transform:translateY(-2px)}</style>
